import React, { useState, useEffect } from 'react';
import QRCode from 'react-qr-code';
import { useTheme } from '../context/ThemeContext';

const SimpleQRCode = ({ plan, onClose }) => {
  const { isDarkMode } = useTheme();
  const [upiId] = useState('amrutanshu20003-16@oksbi');
  const [qrValue, setQrValue] = useState('');
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    // Generate UPI payment string
    const upiString = `upi://pay?pa=${upiId}&pn=MilkMitra&am=${plan.price}&cu=INR&tn=Subscription_${plan.name}`;
    setQrValue(upiString);
  }, [plan]);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(upiId);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (error) {
      console.error('Failed to copy:', error);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[10000] p-4">
      <div className={`relative ${isDarkMode ? 'bg-gray-900' : 'bg-white'} rounded-2xl p-6 max-w-md w-full mx-auto shadow-2xl`}>
        {/* Close Button */}
        <button
          onClick={onClose}
          className={`absolute top-4 right-4 p-2 rounded-lg ${isDarkMode ? 'hover:bg-gray-800' : 'hover:bg-gray-100'} transition-colors`}
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>

        {/* Header */}
        <div className="text-center mb-6">
          <h3 className={`text-xl font-bold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
            Complete Your Subscription
          </h3>
          <p className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
            Scan QR code or pay to UPI ID
          </p>
        </div>

        {/* Plan Details */}
        <div className={`rounded-xl p-4 mb-4 ${isDarkMode ? 'bg-gray-800' : 'bg-gray-50'}`}>
          <div className="flex justify-between items-center">
            <div>
              <h4 className={`font-semibold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
                {plan.name}
              </h4>
              <p className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
                {plan.duration}
              </p>
            </div>
            <div className={`text-2xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
              ₹{plan.price}
            </div>
          </div>
        </div>

        {/* QR Code */}
        <div className="flex justify-center mb-4">
          <div className={`p-4 rounded-xl ${isDarkMode ? 'bg-white' : 'bg-gray-100'}`}>
            {qrValue && (
              <QRCode
                value={qrValue}
                size={180}
                level="H"
                bgColor={isDarkMode ? '#FFFFFF' : '#F3F4F6'}
                fgColor="#000000"
              />
            )}
          </div>
        </div>

        {/* UPI ID */}
        <div className={`rounded-xl p-3 mb-4 ${isDarkMode ? 'bg-gray-800' : 'bg-gray-50'}`}>
          <div className={`text-xs ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} mb-2 text-center`}>
            Or pay to UPI ID
          </div>
          <div className="flex items-center gap-2">
            <code className={`flex-1 ${isDarkMode ? 'bg-gray-900 text-gray-300' : 'bg-white text-gray-800'} px-3 py-2 rounded-lg text-sm font-mono border text-center`}>
              {upiId}
            </code>
            <button
              onClick={handleCopy}
              className={`p-2 rounded-lg ${copied ? 'bg-green-500 text-white' : isDarkMode ? 'bg-gray-700 text-gray-300' : 'bg-gray-200 text-gray-700'} transition-colors`}
            >
              {copied ? (
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                </svg>
              ) : (
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
                </svg>
              )}
            </button>
          </div>
        </div>

        {/* Instructions */}
        <div className={`text-xs ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} text-center`}>
          <p>Payment will be verified by admin</p>
          <p>Subscription will be activated after confirmation</p>
        </div>
      </div>
    </div>
  );
};

export default SimpleQRCode;
